findings.codeql_raw_query:
/**
 * @name Code injection via eval in attrs
 * @description User input reaching eval/exec calls in attr._make can lead to code execution
 * @kind path-problem
 * @problem.severity critical
 * @id py/attrs-code-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module AttrsCodeInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for eval/exec calls specifically in attrs
    exists(API::CallNode call |
      call = API::builtin("eval").getACall() and
      call.getArg(0) = sink
    ) or
    exists(API::CallNode call |
      call = API::builtin("exec").getACall() and
      call.getArg(0) = sink
    )
  }
}

module AttrsCodeInjectionFlow = TaintTracking::Global<AttrsCodeInjectionConfig>;
import AttrsCodeInjectionFlow::PathGraph

from AttrsCodeInjectionFlow::PathNode source, AttrsCodeInjectionFlow::PathNode sink
where AttrsCodeInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Code injection in attrs: user input reaches $@.", source.getNode(), "user input"
